 data=read(case['catalog']['path']);ph=raw['phases'].get('measurement',{});rs=ph.get('request_records',[]);mapping=raw['replica_to_family'];slot=raw['slot'];mem=memory_values(raw,data['safe_factor']);ev=ph.get('stability_evidence',{});metrics=ph.get('metrics',{});window=ph.get('window',{});dur=window.get('duration_seconds',120.);task=case['target_task'];target=[r for r in rs if r['task']==task];done=[r for r in target if r['status']=='completed'];G=sum(data['models'][mapping[r['model']]]['role']=='generalist' for r in target);Gc=sum(r['status']=='completed' and data['models'][mapping[r['model']]]['role']=='generalist' for r in target)
